async function runTests() {
  const test = (await import('brittle')).default

  // one thread per core, capped where the suite's contention starts to show
  test.configure({ jobs: Math.min(4, os.availableParallelism()) })
  test.pause()

  await test.load(import.meta.resolve('./pass.js'))
  await test.load(import.meta.resolve('./skip.js'))

  test.resume()
}
